extern "C"
{
    struct KairoPluginHostV1;

    struct KairoPluginV1
    {
        std::uint32_t StructSize;
        std::uint32_t Version;

        void (*OnLoad)(
            KairoPluginHostV1* host);

        void (*OnUnload)();
    };

    using QueryPluginFn =
        bool (*)(
            std::uint32_t requestedABI,
            KairoPluginV1* outPlugin);
}

