Chapter.Code:
queue = changedAssets;

while (!queue.empty())
{
    AssetID changed = queue.pop();

    for (AssetID dependent
         : ReverseDependencies(changed))
    {
        if (dirty.insert(dependent).second)
        {
            queue.push(dependent);
        }
    }
}

